package com.moddingfromamod.levels.shared;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

/**
 * <b>What a level is, as the shared code needs it</b>: its mod id, its level id (the world preset's path, the world
 * module's id and its world files' name), the name players see on the World Type button, and its third-party built-in
 * packs. Pure, so every rule here is a unit test.
 *
 * <p><b>One way to claim a world, for every level.</b> Each level's jar also carries a tiny empty built-in pack of its
 * own, {@code datapacks/level_marker/} (generated by shared/level.gradle). It is ticked with the level's other packs
 * by the World Type, and named in a dedicated server's {@code initial-enabled-packs}; its presence in a world's data
 * configuration is what makes the world the level's ({@link #marks}). So a level with no third-party packs at all
 * claims exactly as one with several.
 *
 * <p>SHARED SOURCE: this file lives once in {@code shared/} and each world's build compiles a copy into the world's own
 * package ({@code com.moddingfromamod.levels.<level>.shared}), so two world jars in one game never carry the same
 * package (FML refuses a split package). Never a jar of its own.
 *
 * @param modid    the level jar's mod id ({@code moddyisle})
 * @param id       the level id ({@code isle}): {@code data/<modid>/worldgen/world_preset/<id>.json},
 *                 {@code worlds/<id>.json}, the world module's id
 * @param typeName the World Type name players see ({@code Moddy Isle})
 * @param packs    the third-party built-in pack folders in the jar ({@code datapacks/<folder>/}), in load order; may be
 *                 empty
 */
public record Level(String modid, String id, String typeName, List<String> packs) {

    /** The folder of the empty marker pack every level jar carries (shared/level.gradle writes it). */
    public static final String MARKER = "level_marker";

    public Level {
        packs = List.copyOf(packs);
        if (packs.contains(MARKER)) {
            throw new IllegalArgumentException(MARKER + " is the generated marker pack, not one of a level's own packs");
        }
    }

    /** Every built-in pack folder the jar offers: the level's own, then the marker. */
    public List<String> allPacks() {
        List<String> out = new ArrayList<>(packs);
        out.add(MARKER);
        return out;
    }

    /** The id prefix NeoForge gives this mod's built-in packs: {@code mod/<modid>:datapacks/}. */
    public String packPrefix() {
        return "mod/" + modid + ":datapacks/";
    }

    /** Every built-in pack's id (the marker's included), as a world's data configuration lists it. */
    public List<String> packIds() {
        List<String> out = new ArrayList<>();
        for (String folder : allPacks()) {
            out.add(packPrefix() + folder);
        }
        return out;
    }

    /** The id of the marker pack, whose presence in a world's data configuration makes the world the level's. */
    public String markPackId() {
        return packPrefix() + MARKER;
    }

    /** True when a world's enabled pack ids hold this level's marker pack. */
    public boolean marks(Collection<String> enabled) {
        return enabled != null && enabled.contains(markPackId());
    }

    /** The saved-data name that records a world was made as this level: {@code data/<modid>_level.dat}. */
    public String markerName() {
        return modid + "_level";
    }

    /** The logger every shared class of this level writes to. */
    public String loggerName() {
        return "moddingfromamod/" + id;
    }
}
